"""Append Battle review controls; prior approved art and controls remain intact."""
from pathlib import Path
p=Path(__file__).resolve().parent;s=(p/'review-before.html').read_text()
section='''<section id="battle-panel">
<h2>Battle menus · four new background drafts</h2>
<p>Restrained restoration · original cool palette · centered layout · through 32:9. The match setup and each fighter-count layout retain their own original geometry. Portraits, names, selections and lighting remain separate game layers. These are unapproved artwork studies; nothing is installed.</p>
<select id="battle-menu" aria-label="Battle background"><option value="cmtype">Battle · match setup</option><option value="chooseF2">Fighter selection · 2 fighters</option><option value="chooseF3">Fighter selection · 3 fighters</option><option value="chooseF4">Fighter selection · 4 fighters</option></select>
<select id="battle-aspect" aria-label="Battle aspect"><option value="4x3">4:3</option><option value="16x10">16:10</option><option value="16x9" selected>16:9</option><option value="21x9">21:9</option><option value="32x9">32:9</option></select>
<select id="battle-view" aria-label="Battle comparison"><option value="side">Side by side</option><option value="wipe">Wipe comparison</option><option value="draft">Draft only</option></select>
<select id="battle-framing" aria-label="Battle framing"><option value="full">Full selected aspect</option><option value="center">Original 4:3 center</option></select>
<button id="battle-bounds" aria-pressed="false">Show original 4:3 area</button>
<div id="battle-comparison" data-mode="side"><div class="battle-grid"><div class="battle-original-card"><strong>Original native textures</strong><div class="frame battle-frame"><img id="battle-original" alt="Original Battle background"><div class="safe battle-safe"></div></div></div><div><strong>New draft · awaiting feedback</strong><div class="frame battle-frame"><img id="battle-draft" alt="Restored widescreen Battle background"><div class="safe battle-safe"></div></div></div></div><div class="frame battle-frame" id="battle-wipe"><img id="battle-wipe-original" alt="Original Battle background beneath wipe"><img id="battle-wipe-draft" alt="New Battle draft revealed by wipe"><div id="battle-divider"></div><div class="safe battle-safe"></div></div></div>
<div id="battle-wipe-controls" hidden><label for="battle-wipe-input">Original / draft divider · <output id="battle-wipe-value">50%</output></label><input id="battle-wipe-input" aria-label="Battle wipe divider" type="range" min="0" max="100" value="50"></div>
<p id="battle-caption" aria-live="polite"></p><p>Original black side margins show where the native 4:3 image ends. The draft center uses the same layout and retains protected frames/posters, source alpha and broad color. Added sides match material continuity and source softness.</p>
<p><a id="battle-original-link" target="_blank" rel="noopener">Open original PNG</a> · <a id="battle-draft-link" target="_blank" rel="noopener">Open draft PNG</a> · <a id="battle-left-link" target="_blank" rel="noopener">Left join · full height</a> · <a id="battle-right-link" target="_blank" rel="noopener">Right join · full height</a></p>
<details id="battle-joins"><summary>Inspect both original 4:3 joins</summary><div class="row"><div><strong>Left boundary</strong><img id="battle-left-join" alt="Left Battle widescreen join" style="max-height:650px;object-fit:contain"></div><div><strong>Right boundary</strong><img id="battle-right-join" alt="Right Battle widescreen join" style="max-height:650px;object-fit:contain"></div></div><p>The boundary lies at the midpoint of each full-height crop.</p></details>
<details><summary>Source-shaped restoration, transparency and raw proposal</summary>
<select id="battle-reference" aria-label="Battle texture reference"><option value="source">Original native</option><option value="faithful">Faithful HD baseline</option></select>
<select id="battle-version" aria-label="Battle texture version"><option value="restrained">Restrained restoration</option><option value="raw">Raw AI proposal · history</option></select>
<select id="battle-channel" aria-label="Battle texture channel"><option value="rgba">Color + transparency</option><option value="alpha">Alpha coverage</option></select>
<select id="battle-bg" aria-label="Battle texture background"><option value="checker">Checkerboard</option><option value="dark">Dark</option><option value="light">Light</option></select>
<div class="row"><div><strong>Original reference</strong><div class="next-texture-stage battle-texture"><img id="battle-texture-original" alt="Original stored Battle texture mosaic"></div></div><div><strong>Selected restoration version</strong><div class="next-texture-stage battle-texture"><img id="battle-texture-draft" alt="Battle stored texture restoration"></div></div></div><p>Stored textures include 32 unused source rows. Original alpha and unused rows are retained in the restrained version. Raw AI proposals show rejected color, geometry or alpha changes and are not the final art.</p></details>
<p><a href="battle-v1/generations.json">Exact prompts, references and raw generations</a> · <a href="battle-v1/references.json">Eight original source texture identities</a> · <a href="battle-v1/restoration-receipt.json">Restoration preservation checks</a> · <a href="battle-v1/bridge-receipt.json">Final join and softness recipe</a> · <a href="battle-v1/course-retry-receipt.json">Source-guided brick alignment</a> · <a href="battle-v1/wide-receipt.json">Initial assembly history</a> · <a href="battle-v1/verification.json">Verification</a></p>
</section>
'''
s=s.replace('<section id="next-panel">',section+'\n<section id="next-panel">',1)
css='''
.battle-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.battle-grid strong{display:block;margin-bottom:8px}#battle-wipe{display:none;position:relative}#battle-wipe-draft{position:absolute;inset:0;clip-path:inset(0 0 0 50%)}#battle-divider{position:absolute;top:0;bottom:0;left:50%;border-left:2px solid #e4ed99;pointer-events:none}#battle-comparison[data-mode="wipe"] .battle-grid{display:none}#battle-comparison[data-mode="wipe"] #battle-wipe{display:block}#battle-comparison[data-mode="draft"] .battle-original-card{display:none}#battle-comparison[data-mode="draft"] .battle-grid{grid-template-columns:1fr}#battle-wipe-controls{max-width:650px;margin:auto}#battle-wipe-input{width:100%;accent-color:#d8e592}@media(max-width:750px){.battle-grid{grid-template-columns:1fr}}
''';s=s.replace('</style>',css+'\n</style>',1)
js='''
function battleWipe(){const v=document.querySelector('#battle-wipe-input').value;document.querySelector('#battle-wipe-draft').style.clipPath='inset(0 0 0 '+v+'%)';document.querySelector('#battle-divider').style.left=v+'%';document.querySelector('#battle-wipe-value').value=v+'%';}
function battleTexture(){const a=document.querySelector('#battle-menu').value,ref=document.querySelector('#battle-reference').value,v=document.querySelector('#battle-version').value,alpha=document.querySelector('#battle-channel').value==='alpha',bg=document.querySelector('#battle-bg').value,suffix=alpha?'-alpha.png':'.png';document.querySelector('#battle-texture-original').src='battle-v1/'+a+'-'+ref+suffix;document.querySelector('#battle-texture-draft').src='battle-v1/'+a+'-'+v+suffix;for(const e of document.querySelectorAll('.battle-texture'))e.dataset.bg=bg;}
function battleMenu(){const a=document.querySelector('#battle-menu').value,center=document.querySelector('#battle-framing').value==='center',r=center?'4x3':document.querySelector('#battle-aspect').value,w=sizes[r],base='battle-v1/'+a,original=base+'-'+r+'-original.png',draft=base+'-'+r+'-draft.png';for(const id of ['battle-original','battle-wipe-original'])document.getElementById(id).src=original;for(const id of ['battle-draft','battle-wipe-draft'])document.getElementById(id).src=draft;document.querySelector('#battle-original-link').href=original;document.querySelector('#battle-draft-link').href=draft;for(const side of ['left','right']){document.querySelector('#battle-'+side+'-link').href=base+'-'+side+'-join.png';document.querySelector('#battle-'+side+'-join').src=base+'-'+side+'-join.png';}document.querySelector('#battle-aspect').disabled=center;const pct=1920/w*100;for(const e of document.querySelectorAll('.battle-safe'))Object.assign(e.style,{width:pct+'%',left:(100-pct)/2+'%'});const mode=document.querySelector('#battle-view').value;document.querySelector('#battle-comparison').dataset.mode=mode;document.querySelector('#battle-wipe-controls').hidden=mode!=='wipe';document.querySelector('#battle-caption').textContent=document.querySelector('#battle-menu').selectedOptions[0].textContent+' · '+labels[r]+' · '+w+'×1440 · '+(center?'matching original center':'centered scenery')+' · unapproved artwork draft · in-game validation pending';battleWipe();battleTexture();}
for(const id of ['battle-menu','battle-aspect','battle-view','battle-framing'])document.getElementById(id).onchange=battleMenu;for(const id of ['battle-reference','battle-version','battle-channel','battle-bg'])document.getElementById(id).onchange=battleTexture;document.querySelector('#battle-wipe-input').oninput=battleWipe;document.querySelector('#battle-bounds').onclick=e=>{const show=e.target.getAttribute('aria-pressed')!=='true';for(const f of document.querySelectorAll('.battle-frame'))f.classList.toggle('show',show);e.target.setAttribute('aria-pressed',String(show));};battleMenu();
'''
s=s.replace('</script>',js+'\n</script>',1);(p.parent/'review.html').write_text(s);print('Battle panel added; previous controls/art records retained')
